// Builds worker/discord-feed.js: the one file Cloudflare runs, from worker/index.mjs, calls.js, worker/feed-core.js and
// (for the Telegram feed) worker/telegram.mjs with the teleproto library. Run: node worker/bundle.js
// The Worker needs the nodejs_compat compatibility flag: Node built-ins become imports of Cloudflare's node:* modules.
// Telegram code is loaded only when TG_SESSION is set (esbuild keeps the dynamic import lazy), so a Discord-only
// Worker doesn't pay its start-up cost.
const fs = require('node:fs');
const path = require('node:path');
const { builtinModules } = require('node:module');

const OUT = path.join(__dirname, 'discord-feed.js');
const HEADER = '// GENERATED by `node worker/bundle.js` from worker/index.mjs, calls.js, worker/feed-core.js, worker/telegram.mjs and teleproto. Do not edit.\n';
const BUILTINS = new Set(builtinModules.filter((m) => !m.startsWith('_')));

// require('fs') inside CommonJS packages -> Cloudflare's own node:fs module object (its default export), the same way
// wrangler does it: an ES module namespace would be read-only, and some packages (graceful-fs) patch what they get.
const nodeBuiltins = {
  name: 'node-builtins',
  setup(build) {
    build.onResolve({ filter: /^(node:)?[a-z_/]+$/ }, (args) => {
      const name = args.path.replace(/^node:/, '');
      if (!BUILTINS.has(name)) return undefined;
      if (args.namespace === 'node-shim') return { path: 'node:' + name, external: true };
      return { path: name, namespace: 'node-shim' };
    });
    build.onLoad({ filter: /.*/, namespace: 'node-shim' }, (args) => ({ contents: `import lib from 'node:${args.path}';\nmodule.exports = lib;\n`, loader: 'js' }));
  },
};

async function bundle() {
  const esbuild = require('esbuild');
  const r = await esbuild.build({
    absWorkingDir: path.join(__dirname, '..'), // paths in the output are relative to the repo, the same from any folder
    entryPoints: [path.join(__dirname, 'index.mjs')],
    bundle: true,
    format: 'esm',
    platform: 'neutral',
    mainFields: ['module', 'main'],
    target: 'es2022',
    write: false,
    legalComments: 'none',
    logLevel: 'silent',
    plugins: [nodeBuiltins],
  });
  return HEADER + r.outputFiles[0].text;
}

if (require.main === module) {
  bundle().then((text) => { fs.writeFileSync(OUT, text); console.log(`wrote worker/discord-feed.js (${Math.round(text.length / 1024)} KB)`); }, (e) => { console.error(e); process.exit(1); });
}
module.exports = { bundle, nodeBuiltins };
